  "claim_id": "C037",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C037.component",
    "value": "Repeated comparable observations can help distinguish an enduring turnaround constraint from a short-lived disruption.",
    "scope": "A possible inferential contribution, conditional on repetition and comparability; no successful distinction is reported.",
    "provenance": {
      "refs": [
        {
          "source_id": "P020",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited span directly attributes this qualified distinguishing capability to repeated comparable observations."
    }
  },
  "signal_basis": {
    "component_id": "C037.signal_basis",
    "value": "Comparable observations reveal temporal differences between recurring stage-specific delays and isolated spikes followed by recovery. The provisional persistence rule requires recurrence on multiple booking days in each investigation week, with the same stage carrying the greatest documented delay burden in both weeks.",
    "scope": "Prospective signals assumed observed for this judgment, rather than reported findings. Interpretation remains limited by measurement and workload changes, missingness, sparse observations, and the two-week window; the persistence rule supplies neither statistical proof nor causal identification.",
